    "car_join_2_desc": "We read every application and reply by email within 48 hours.",
    "car_join_3_title": "Start teaching",
    "car_join_3_desc": "Once approved, open your teacher dashboard, set your weekly availability and lead your first live class.",
    "corp_hero_desc": "Language training for your team and for the people you relocate: private live classes with experienced teachers, focused on your workplace.",
    "corp_contact_btn": "Contact us",
    "corp_why_1_title": "Experienced teachers",
    "corp_why_1_desc": "Live classes led by experienced teachers, in a private group for your company or one to one for managers.",
    "corp_why_2_title": "Workplace-focused lessons",
    "corp_why_2_desc": "Lessons, notes and homework built around your field and the situations your team meets at work.",
    "corp_why_3_title": "Relocation and certificates",
    "corp_why_3_desc": "Employees can start before they move. They practise in the format of IELTS, B2 First and C1 Advanced for English, and Goethe B1, Goethe B2 and telc B1 for German, the certificates many visas and work permits ask for. Not official exam material.",
    "corp_why_4_title": "The right level for everyone",
    "corp_why_4_desc": "A short placement test finds each employee’s level between A1 and C1, so classes start where they are and nobody repeats what they already know.",
    "corp_cta_title_1": "Let's talk",
    "corp_cta_title_2": "about your team",
    "corp_price_desc": "Pricing depends on the size of your team and what you need. Get in touch and we will put together a quote.",
    "services_slide_1_desc": "Submit a written answer and get a score out of 100, with feedback on what worked, one or two specific corrections and one tip.",
    "services_slide_2_desc": "Multiple-choice, fill-in and word-matching exercises are marked as soon as you answer, with the correct answer and a short explanation of the rule.",
    "services_slide_3_desc": "Your teacher grades your homework (score, strengths, what to work on next, an example correction) and sends the feedback to your dashboard.",
    "services_slide_4_desc": "Read the sentence aloud. Speech recognition writes down what you said and shows how many of the expected words it heard.",
    "services_slide_5": "Error Correction",
    "services_slide_5_desc": "Chat in the language you’re learning. Each message is checked for grammar, vocabulary and spelling, and you see the corrected sentence with a short explanation.",
    "services_slide_6": "Vocabulary Review",
    "services_slide_6_desc": "Words from your teacher’s lesson notes become flashcards. Words you know come back after 1, 3, 7, 14 and 30 days; words you miss come back the next day.",
    "services_slide_7": "Exam Prep",
    "services_slide_7_desc": "Practice tasks in the format of B2 First, C1 Advanced and IELTS (English) and Goethe B1, Goethe B2 and telc B1 (German). Not official exam material; Alimun is not affiliated with the exam boards.",
    "services_slide_8": "Placement Test",
    "services_slide_8_desc": "Eight questions from A1 up to C1. Your result sets your level, so your exercises and classes match it.",
    "services_how_title": "How it works",
    "services_how_1_title": "Find your level",
    "services_how_1_desc": "A short placement test sets your level, from A1 to C1, and your exercises and classes match it.",
    "services_how_2_title": "Learn live",
    "services_how_2_desc": "Video classes with your teacher and the same group, on fixed days and at a fixed time every week.",
    "services_how_3_title": "Keep the class with you",
    "services_how_3_desc": "After each class your teacher shares the session notes, the new vocabulary and your homework.",
    "services_how_4_title": "Hand in your assignments",
    "services_how_4_desc": "Your teacher sets homework with a due date. You submit it in your dashboard and get it back graded, with a score, what went well, what to work on next and an example correction.",
    "services_how_5_title": "Practice whenever you want",
    "services_how_5_desc": "A practice library at your level, with multiple choice, fill-in-the-blank, word matching, listening, speaking and essay exercises, all with instant feedback, plus flashcards for the words from your lessons.",
    "services_how_6_title": "Tests and exam preparation",
    "services_how_6_desc": "Quizzes and tests are marked the moment you finish. Working toward a certificate? Practice tasks in the format of B2 First, C1 Advanced and IELTS for English, and Goethe B1, Goethe B2 and telc B1 for German.",
    "services_how_6_note": "Not official exam material. Alimun is not affiliated with the exam boards.",
