    "corporate_slide_7": "Habla con fluidez. De por vida. <span class=\"alimun-cta-highlight\">Alimun Corporate</span>.",
    "corporate_form_title": "Solicitar demostración",
    "corporate_form_desc": "Descubre cómo Alimun puede acelerar la preparación para la reubicación de tus empleados.",
