    "corporate_why_1_title": "Enseignants experts en expatriation",
    "corporate_why_1_desc": "Experts linguistiques natifs spécialisés dans l'intégration des expatriés, la culture d'entreprise locale et la conversation professionnelle.",
    "corporate_why_2_title": "Cours collectifs par métier",
    "corporate_why_2_desc": "Les collaborateurs apprennent ensemble en petits groupes organisés par fonction, en simulant des situations professionnelles concrètes.",
    "corporate_why_3_title": "Progression assistée par IA",
    "corporate_why_3_desc": "Notre moteur d'IA automatise l'apprentissage du vocabulaire et les corrections, libérant du temps pour la pratique orale avec l'enseignant.",
    "corporate_why_4_title": "Tableau de bord RH",
    "corporate_why_4_desc": "Suivez les présences, les heures de conversation active et les étapes clés du CECRL grâce à des analyses en temps réel.",
    "corporate_process_title": "Comment ça marche",
    "corporate_step_1_title": "1. Évaluation des compétences",
    "corporate_step_1_desc": "Nous évaluons le niveau d'expression orale de vos employés et les associons à leurs destinations de relocalisation.",
    "corporate_step_2_title": "2. Groupes sur-mesure",
    "corporate_step_2_desc": "Les employés rejoignent des groupes de conversation privés adaptés à leur fonction et à leurs objectifs.",
    "corporate_step_3_title": "3. Lancement et suivi",
    "corporate_step_3_desc": "Les cours commencent selon votre calendrier, et les RH reçoivent chaque mois des rapports détaillés de présence et de progression.",
