    "corporate_form_submit": "Envoyer la demande →",
    "corporate_t1_desc": "Avec 18 ans d'expérience, Sarah est spécialisée dans la préparation à l'expatriation des cadres dirigeants s'installant en Espagne et en Amérique latine.",
    "corporate_t2_desc": "Jessica apporte 22 ans de formation linguistique, concevant des modules de vocabulaire sur-mesure pour les équipes techniques, financières et d'ingénierie.",
    "corporate_t3_desc": "Linguiste bilingue avec 15 ans de coaching d'expatriés. Martina anime nos groupes d'immersion, en se concentrant sur les codes d'affaires locaux.",
    "corporate_t4_desc": "Avec 20 ans d'expérience auprès de dirigeants multinationaux, Kevin anime des modules de rédaction professionnelle, de présentation et de négociation.",
    "corporate_cta_text_1": "Vous relocalisez des salariés ?",
    "corporate_cta_text_2": "Besoin d'enseignants natifs ?",
