    "corp_huge_slide_2": "94 % des affectations internationales échouent lorsque <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">la préparation linguistique est ignorée</span>.",
    "corp_huge_slide_3": "L'échec d'une relocalisation coûte cher. La langue est <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">votre protection ultime</span>.",
    "corp_huge_slide_4": "Les équipes bilingues instaurent <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">une confiance immédiate et une crédibilité locale</span>.",
    "corp_huge_slide_5": "La maîtrise fluidifie les opérations, <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">minimisant les temps morts et les goulots d'extranglement</span>.",
    "corp_huge_slide_6": "Valorisez vos expatriés avec <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">des groupes d'entreprise professionnels</span>.",
