    "careers_hero_title": "Unterrichten Sie von überall. Bestimmen Sie Ihre Arbeitszeiten.",
    "careers_hero_subtitle": "Leiten Sie aktive Konversationskohorten für motivierte Lernende weltweit.",
    "careers_cta_apply": "Als Lehrkraft bewerben",
    "careers_why_title": "Warum bei Alimun unterrichten?",
    "careers_why_1_title": "Gruppen-Hebel",
    "careers_why_1_desc": "Wiederholen Sie nicht dieselbe Anfängerlektion 20-mal im Einzelunterricht. Leiten Sie eine Gruppe und lassen Sie die Gruppe interagieren.",
    "careers_why_2_title": "KI-Korrektur-Assistent",
    "careers_why_2_desc": "Unsere KI prüft Vokabeln und Grammatikübungen. Sie konzentrieren sich ganz auf das Sprechen und Feedback in Echtzeit.",
    "careers_why_3_title": "Stabiles Einkommen",
    "careers_why_3_desc": "Erhalten Sie eine verlässliche Vergütung pro aktiver Gruppe. Je größer Ihre Gruppen werden, desto mehr verdienen Sie.",
    "careers_process_title": "Bewerbungsverfahren",
    "careers_process_desc": "Wir nehmen weniger als 5% der Bewerber auf, um unseren hohen Standard zu sichern.",
    "careers_step_1_title": "Online-Bewerbung",
    "careers_step_1_desc": "Reichen Sie Ihren Lebenslauf, Qualifikationen und ein kurzes 2-minütiges Vorstellungsvideo ein.",
    "careers_step_2_title": "Probestunde",
    "careers_step_2_desc": "Leiten Sie eine 30-minütige Probestunde mit einer kleinen Gruppe von aktiven Alimun-Schülern.",
    "careers_step_3_title": "Kurs-Start",
    "careers_step_3_desc": "Schließen Sie das Onboarding ab und starten Sie Ihre erste offizielle Konversationskohorte.",
    "careers_form_title": "Bewerbung starten",
    "careers_form_desc": "Füllen Sie das Formular aus, um sich zu bewerben.",
    "careers_form_language": "Welche Sprache unterrichten Sie?",
    "careers_form_experience": "Jahre Lehrerfahrung",
    "careers_form_video": "Link zum Vorstellungsvideo (Loom, YouTube, etc.)",
    "careers_form_submit": "Bewerbung abschicken",
    "careers_hero_desc": "Unterrichten Sie zu Ihren eigenen Bedingungen. Alimun kombiniert Live-Konversationskohorten mit KI-gestütztem Feedback und automatisiert die gesamte Benotung, sodass Sie sich voll und ganz auf die Live-Interaktion mit den Schülern, das Mentoring in Kleingruppen und die aktive Praxis konzentrieren können.",
    "careers_t1_desc": "Den Lehrplan für Gruppenkurse bei Alimun zu entwerfen, war ein echter Wendepunkt. Ich unterrichte viele Lernende gleichzeitig, ohne auszubrennen.",
    "careers_t2_desc": "Die KI von Alimun übernimmt alle Vokabelübungen und Benotungen. Ich verbringe 100 % meiner Unterrichtszeit mit dem, was ich liebe: Schülern beim Sprechen zu helfen.",
    "careers_t3_desc": "Das Kleingruppenmodell ist so viel interaktiver und motivierender, als den ganzen Tag lang sich wiederholende Einzelstunden zu geben.",
    "careers_t4_desc": "Zuverlässige Honorare pro aktiver Gruppe bieten mir eine hervorragende Einkommensstabilität bei gleichzeitig völlig flexibler Zeiteinteilung.",
    "careers_cta_ready_title": "Bereit zu unterrichten?",
    "careers_carousel_1": "Müde von wiederholenden Einzelstunden?",
    "careers_carousel_2": "Möchten Sie Ihren Einfluss vergrößern?",
    "careers_carousel_3": "Wünschen Sie flexible Arbeitszeiten?",
    "careers_carousel_4": "Unterrichten Sie bei Alimun.",
    "careers_why_4_title": "Flexible Arbeitszeiten",
    "careers_why_4_desc": "Bestimmen Sie Ihre Verfügbarkeit und Ihren Unterrichtsplan selbst. Unterrichten Sie von überall auf der Welt.",
    "careers_sim_sub_1": "Müde, mit Einzelunterricht <span class=\"alimun-cta-highlight\">nicht genug Geld</span> zu verdienen?",
    "careers_sim_sub_2": "Die meisten Plattformen verlangen bis zu <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">33 % Provision</span>.",
    "careers_sim_sub_3": "Bei Alimun verlangen wir <span class=\"alimun-cta-highlight\">30 %</span>.",
    "careers_sim_sub_4": "Zudem können Sie bis zu <span class=\"alimun-cta-highlight\">15 Schüler</span> gleichzeitig unterrichten!",
    "careers_sim_sub_5": "KI übernimmt die Benotung. <span class=\"alimun-cta-highlight\">Fokus auf die Live-Praxis</span>.",
    "careers_sim_sub_6": "Verdienen Sie bis zu <span class=\"alimun-cta-highlight\">80 €/Std.</span> bei flexibler Zeiteinteilung.",
    "careers_sim_sub_7": "Fließend sprechen. Fürs Leben. <span class=\"alimun-cta-highlight\">Unterrichten bei Alimun</span>.",
    "corporate_hero_title": "unternehmenslösungen",
    "corporate_hero_desc": "Stellen Sie sicher, dass Ihre entsandten Mitarbeiter vom ersten Tag an fließend sprechen. Alimun verbindet professionelle, rollenspezifische Gruppen mit muttersprachlichen Relocation-Lehrern und KI-Verfolgung.",
    "corporate_cta_demo": "Demo anfordern",
    "corporate_why_title": "Mitarbeiter-Fluenz",
    "corporate_why_1_title": "Spezialisierte Relocation-Lehrer",
    "corporate_why_1_desc": "Muttersprachliche Sprachexperten, spezialisiert auf Expat-Integration, lokale Geschäftskultur und professionelle Konversation.",
    "corporate_why_2_title": "Rollenbezogene Gruppen",
    "corporate_why_2_desc": "Mitarbeiter lernen gemeinsam in kleinen Gruppen, sortiert nach Aufgabenbereich, und üben realistische Arbeitsplatzszenarien.",
    "corporate_why_3_title": "KI-gestützter Fortschritt",
    "corporate_why_3_desc": "Unsere KI automatisiert Vokabelübungen und Benotungen und maximiert die Zeit für direkte Sprechübungen mit Lehrern.",
    "corporate_why_4_title": "HR-Admin-Dashboard",
    "corporate_why_4_desc": "Verfolgen Sie Anwesenheit, aktive Sprechzeit und GER-Kompetenzstufen durch Echtzeit-Analysen.",
    "corporate_process_title": "Wie es funktioniert",
    "corporate_step_1_title": "1. Kompetenzanalyse",
    "corporate_step_1_desc": "Wir bewerten das Sprachniveau Ihrer Mitarbeiter und stimmen es auf den Entsendungsort ab.",
    "corporate_step_2_title": "2. Eigene Gruppen",
    "corporate_step_2_desc": "Mitarbeiter treten privaten Konversationskohorten bei, die auf ihre Aufgaben und Sprachziele abgestimmt sind.",
    "corporate_step_3_title": "3. Start & Auswertung",
    "corporate_step_3_desc": "Der Unterricht startet flexibel, und HR erhält monatliche Audits zu Fortschritten und Anwesenheit.",
    "corporate_slide_1": "Sie versetzen Ihr <span class=\"alimun-cta-highlight\">Team ins Ausland</span>?",
    "corporate_slide_2": "Es kann schon <span class=\"alimun-cta-highlight\">vor dem Umzug</span> beginnen.",
