    "corporate_form_submit": "Anfrage absenden →",
    "corporate_t1_desc": "Mit 18 Jahren Erfahrung ist Sarah auf die intensive Relocation-Vorbereitung für Führungskräfte spezialisiert, die nach Spanien oder Lateinamerika umziehen.",
    "corporate_t2_desc": "Jessica bringt 22 Jahre Sprachtraining ein und erstellt maßgeschneiderte Vokabelmodule für Support-, Finanz- und Ingenieurteams.",
    "corporate_t3_desc": "Bilinguale Linguistin mit 15 Jahren Expat-Coaching. Martina leitet unsere Immersionskohorten mit Fokus auf lokale Geschäftsetikette.",
    "corporate_t4_desc": "Mit 20 Jahren Erfahrung im Coaching internationaler Vorstände leitet Kevin Module für Geschäftskorrespondenz, Präsentationen und Verhandlungen.",
