    "corporate_cta_text_4": "Kontaktieren Sie Alimun.",
    "corp_huge_slide_1": "Globale Expansion <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">erfordert globale Sprachgewandtheit</span>.",
    "corp_huge_slide_2": "94 % der Auslandsberufe scheitern, wenn <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">die sprachliche Vorbereitung ignoriert wird</span>.",
    "corp_huge_slide_3": "Fehlgeschlagene Entsendungen sind teuer. Sprachvorbereitung ist <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">Ihre beste Absicherung</span>.",
    "corp_huge_slide_4": "Bilinguale Teams schaffen <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">sofortiges Vertrauen und lokale Glaubwürdigkeit</span>.",
    "corp_huge_slide_5": "Fluenz erleichtert lokale Abläufe und <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">minimiert Ausfallzeiten und Engpässe</span>.",
    "corp_huge_slide_6": "Stärken Sie Ihre Expats mit <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">professionellen Unternehmenskohorten</span>.",
    "corp_huge_slide_7": "Fließend sprechen. Fürs Leben. <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">Alimun Corporate</span>.",
