    "tiers_plan_1_desc": "Uma aula ao vivo por semana, anotações da sessão com o vocabulário novo e acesso à comunidade.",
    "tiers_plan_2_desc": "Duas aulas ao vivo por semana em uma turma menor, feedback sobre o seu trabalho toda semana, redações corrigidas e um relatório mensal de progresso.",
    "tiers_plan_3_desc": "Três aulas ao vivo por semana em uma turma quase particular, uma sessão individual toda semana e um percurso feito para você.",
    "tiers_plan_4_desc": "Aulas particulares com o seu próprio professor, com base em três aulas por semana, um programa feito em torno de você e aulas extras quando precisar.",
    "tiers_choose": "Escolher este plano",
    "tiers_hero_lead": "Aulas de idiomas ao vivo com um professor, a partir de €24 por mês. Escolha o tamanho da sua turma e quantas vezes por semana quer ter aula, e mude de plano quando os seus objetivos mudarem.",
    "tiers_hero_cta": "Ver os planos",
    "tiers_pc_title": "Quanto custa uma aula ao vivo",
    "tiers_pc_desc": "Escolha um plano para ver o preço de uma aula ao vivo, calculado a partir do preço mensal e das aulas que você tem em um mês de cerca de 4,3 semanas.",
    "tiers_pc_unit": "por aula ao vivo",
    "tiers_pc_line_1": "Uma aula ao vivo por semana, cerca de 4 por mês, por {price} por mês.",
    "tiers_pc_line_2": "Duas aulas ao vivo por semana, cerca de 9 por mês, por {price} por mês.",
    "tiers_pc_line_3": "Três aulas em grupo e uma sessão individual por semana, cerca de 17 por mês, por {price} por mês.",
    "tiers_pc_line_4": "Três aulas particulares por semana, cerca de 13 por mês, por {price} por mês.",
    "tiers_pc_year": "No plano anual: cerca de {price} por aula.",
    "tiers_faq_title": "Perguntas sobre planos e preços",
    "tiers_faq_q1": "Posso cancelar quando quiser?",
    "tiers_faq_a1": "Sim. Você pode cancelar a qualquer momento nas configurações de pagamento da sua conta e mantém o acesso até o fim do período pago, como previsto nos Termos e Condições.",
    "tiers_faq_q2": "Como funciona o plano anual?",
    "tiers_faq_a2": "Você paga uma vez por ano e tem doze meses pelo preço de dez. O Community, por exemplo, custa €240 por ano em vez de €24 todo mês.",
    "tiers_faq_q3": "Posso mudar de plano depois?",
    "tiers_faq_a3": "Sim. Você pode passar para outro plano quando os seus objetivos mudarem. Se precisar de ajuda para escolher, escreva para nós pela página de contato.",
    "tiers_faq_q4": "Em que moeda eu pago?",
    "tiers_faq_a4": "Mostramos os preços na sua moeda quando possível, em euros, dólares americanos, canadenses ou australianos ou dirhams marroquinos, e você paga na moeda mostrada na página.",
    "tiers_faq_q5": "E se o meu idioma ainda não estiver aberto?",
    "tiers_faq_a5": "Você pode entrar gratuitamente na lista de espera sem pagar nada hoje. Avisamos você assim que as aulas no seu idioma abrirem, e as aulas de inglês e alemão já estão abertas.",
    "services_hero_title_v2": "Aulas de idiomas online",
    "services_hero_desc_v2": "Aulas ao vivo por vídeo com o seu professor e sempre a mesma turma, em dias fixos toda semana. Entre as aulas, os exercícios e testes são corrigidos assim que você responde, e o seu professor corrige as suas tarefas.",
    "services_btn_how": "Veja como funciona",
    "services_tools_title": "Prática entre as aulas",
    "services_tools_desc": "Entre as aulas ao vivo, você continua avançando sozinho. Os exercícios e testes são corrigidos assim que você responde, e o seu professor corrige as suas tarefas.",
    "services_title": "Seu caminho para a fluência: Escolha o seu acesso.",
