    "corporate_t3_desc": "Linguista cognitiva bilíngue com 15 anos de coaching. Martina lidera nossas turmas de imersão em realocação e etiqueta corporativa local.",
    "corporate_t4_desc": "Com 20 anos de experiência com executivos multinacionais, Kevin dirige módulos de escrita comercial, apresentações e negociação de contratos.",
