    "corp_hero_title": "提升您团队的全球化语言能力",
    "corp_hero_subtitle": "专为现代企业打造的小班制（Cohort）语言培训方案。",
    "corp_cta_chat": "在线咨询",
    "corp_cta_chat_desc": "与我们的企业解决方案团队联系，定制适合您公司成长步伐的语言培训计划。",
    "corp_features_title": "为什么 Alimun 适合企业团队",
    "corp_feature_1_title": "定制岗位课程",
    "corp_feature_1_desc": "针对销售、客户支持或技术团队的专业词汇与日常场景进行量身定制设计。",
    "corp_feature_2_title": "活跃小班练习",
