    "corp_feature_3_title": "HR 进度仪表盘",
    "corp_feature_3_desc": "实时跟踪考勤、口语时长及 AI 评定的流利度里程碑，报告公开透明。",
    "corp_tiers_title": "企业解决方案",
    "corp_tier_1_title": "专属团队班",
    "corp_tier_1_desc": "专为 5 至 15 人团队设立。非常适合需要跨国合作的部门。",
    "corp_tier_2_title": "企业授权许可",
    "corp_tier_2_desc": "全公司范围内的灵活访问，定制课程表、专属技术支持和定制结算发票。",
    "corp_form_title": "企业合作咨询",
    "corp_form_desc": "告诉我们您团队的语言培训需求，我们将为您提供定制方案。",
    "corp_form_company": "公司名称",
    "corp_form_employees": "员工人数",
    "corp_form_submit": "申请定制方案",
    "careers_hero_title": "不受地域限制教学，自主决定收入",
    "careers_hero_subtitle": "带领全球有强大学习动机的学员进行活跃的口语小班直播课教学。",
    "careers_cta_apply": "申请成为教师",
    "careers_why_title": "为什么选择在 Alimun 教学？",
    "careers_why_1_title": "小班制的高效杠杆",
    "careers_why_1_desc": "告别重复了 20 次的枯燥一对一基础课。教授结构化的小组课并引导学员互动。",
    "careers_why_2_title": "AI 辅助打分工具",
    "careers_why_2_desc": "我们的 AI 负责词汇检查和语法练习。你只需专注于实时交流与点评。",
    "careers_why_3_title": "稳定的收入回报",
    "careers_why_3_desc": "每个活跃班级都有稳定的基底薪酬。随着班级壮大，你的收益也会按比例增长。",
    "careers_process_title": "甄选流程",
    "careers_process_desc": "我们仅录用少于 5% 的申请者，以保持高标准的教学质量。",
    "careers_step_1_title": "在线申请",
    "careers_step_1_desc": "提交您的简历、教学资质证书以及一段 2 分钟的简短视频自我介绍。",
    "careers_step_2_title": "教学试讲",
    "careers_step_2_desc": "带领一节 30 分钟的试讲课，与 Alimun 的活跃学员小组进行互动。",
    "careers_step_3_title": "上线开课",
    "careers_step_3_desc": "完成教师入职引导，设定您的时间表，并开启您的首个官方口语班。",
    "careers_form_title": "开始申请",
    "careers_form_desc": "填写初步申请表，预约教学面试席位。",
    "careers_form_language": "您教授什么语言？",
    "careers_form_experience": "教学经验（年）",
    "careers_form_video": "自我介绍视频链接 (Loom, 腾讯视频, YouTube 等)",
    "careers_form_submit": "提交申请",
    "careers_hero_desc": "按照您自己的方式进行教学。Alimun 将在线口语直播课 with AI 智能反馈相结合，实现所有作业自动打分，让您能够完全专注于学员互动、小班指导和口语实践。",
    "careers_t1_desc": "在 Alimun 设计小班制课程是一个重大突破。我能够同时指导许多学生，而不会感到疲惫不堪。",
    "careers_t2_desc": "Alimun 的 AI 负责所有的词汇练习和作业评分。我可以把 100% of 的课上时间用来做我最喜欢的事：帮助学员开口说话。",
    "careers_t3_desc": "分小组练习的模式非常具有互动性和活力，比整天重复枯燥的一对一课程要有趣得多。",
    "careers_t4_desc": "稳定的班级基础薪酬为我提供了极好的收入保障，同时我还能保持完全自由的时间表安排。",
    "careers_cta_ready_title": "准备好加入教学了吗？",
    "careers_carousel_1": "厌倦了重复的一对一课程吗？",
    "careers_carousel_2": "想扩大您的教学影响力吗？",
    "careers_carousel_3": "想要自由安排时间表吗？",
    "careers_carousel_4": "在 Alimun 教学。",
    "careers_why_4_title": "灵活的工作时间",
    "careers_why_4_desc": "自主决定您的授课时间与班级课表。在世界任何地方进行在线教学。",
    "careers_sim_sub_1": "厌倦了一对一私教课那 <span class=\"alimun-cta-highlight\">微薄的收入</span> 吗？",
    "careers_sim_sub_2": "大多数平台都会抽取高达 <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">33% 的佣金提成</span>。",
    "careers_sim_sub_3": "Alimun 收取 <span class=\"alimun-cta-highlight\">30%</span> 佣金。",
    "careers_sim_sub_4": "此外，小班模式让您可以同时指导多达 <span class=\"alimun-cta-highlight\">15 名学生</span>！",
    "careers_sim_sub_5": "AI 助教自动批改作业，让您能 <span class=\"alimun-cta-highlight\">专注于现场口语教学</span>。",
    "careers_sim_sub_6": "赚取高达 <span class=\"alimun-cta-highlight\">每小时 80 欧元</span>，享有完全时间弹性。",
    "careers_sim_sub_7": "流利表达。终生受益。<span class=\"alimun-cta-highlight\">在 Alimun 授课</span>。",
    "corporate_hero_title": "企业解决方案",
    "corporate_hero_desc": "确保您的外派员工从第一天起就能流利交流。Alimun 将针对特定岗位的专业小班课程、母语专业教师以及 AI 进度跟踪完美结合。",
    "corporate_cta_demo": "申请试听",
    "corporate_why_title": "员工语言流利度",
    "corporate_why_1_title": "海外派遣语言教师",
    "corporate_why_1_desc": "母语语言专家，专攻外派员工融合、当地商业文化和专业职场对话。",
    "corporate_why_2_title": "针对特定岗位的小班课",
    "corporate_why_2_desc": "同一工作职能（技术、财务、管理）的员工组成小组共同学习，练习真实的职场工作场景。",
    "corporate_why_3_title": "AI 驱动进度监测",
    "corporate_why_3_desc": "我们的 AI 引擎可自动完成词汇练习和打分，确保员工在课堂上能最大限度地与教师进行真人对话。",
    "corporate_why_4_title": "HR 管理后台",
    "corporate_why_4_desc": "通过实时分析追踪员工的出勤率、有效对话时长以及 CEFR 语言等级里程碑。",
    "corporate_process_title": "如何运作",
    "corporate_step_1_title": "1. 语言水平评估",
    "corporate_step_1_desc": "我们评估您员工的口语水平，并结合他们的外派目的地进行水平匹配。",
    "corporate_step_2_title": "2. 定制专属班级",
    "corporate_step_2_desc": "员工加入与其岗位和语言目标相匹配的私人企业对话小班课。",
    "corporate_step_3_title": "3. 开课与进度跟踪",
    "corporate_step_3_desc": "根据您的时间表灵活上课，HR 每月将收到出勤和学习进度审计报告。",
    "corporate_slide_1": "要把你的<span class=\"alimun-cta-highlight\">团队派往海外</span>吗？",
    "corporate_slide_2": "他们可以<span class=\"alimun-cta-highlight\">出发前就开始学习</span>。",
    "corporate_slide_3": "由<span class=\"alimun-cta-highlight\">资深教师</span>授课的直播课。",
