    "corp_huge_slide_1": "全球业务扩张 <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">需要全球化的语言流利度</span>。",
    "corp_huge_slide_2": "如果忽视 <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">语言储备</span>，94% 的国际派遣任务都会以失败告终。",
    "corp_huge_slide_3": "海外派遣失败代价高昂。语言储备是 <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">您最核心的安全保障</span>。",
    "corp_huge_slide_4": "双语团队能够与当地建立 <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">即时的信任和本地公信力</span>。",
