    "about_hero_title": "我们的故事",
    "about_hero_desc": "由语言老师创办：我们厌倦了看着优秀的学生在昂贵又不频繁的一对一课程中停滞不前。Alimun 把规律的直播课与即时批改的练习结合起来，让进步在课与课之间也能发生。",
    "about_btn_waitlist": "加入候补名单",
    "about_history_title": "真实流畅度标准",
    "about_history_desc": "从第一天起就围绕一个理念构建：如果由 AI 处理重复性的批改，优秀的老师可以同时指导多名学生。这一信念塑造了我们推出的每个级别、每门课程和每个功能。",
    "about_history_eyebrow": "我们的历史",
    "about_history_y1_desc": "Alimun 由语言教师创立",
