    "about_staff_title": "结识我们的老师",
    "about_staff_1_desc": "Sarah 拥有 18 年的教学经验，负责设计 Community 级别的课程——旨在让零基础的学员从第一周起就养成真正的学习习惯。",
    "about_staff_2_desc": "Jessica 拥有 22 年的课堂教学经验，擅长帮助犹豫不决的中级学员转变为自信、流利的口语表达者。",
    "about_staff_3_desc": "Martina 是一位拥有 15 年教学经验的语言学家，负责主持我们的 Micro-Group 课程，以纠正阻碍学员进步的细微错误而闻名。",
    "about_staff_4_desc": "Kevin 拥有 20 年经验，负责我们的小班定制课程（Intensive 1:1），深受需要完全个性化计划和每周督学的学员喜爱。",
    "services_hero_title": "工具箱",
    "services_hero_desc": "每篇作文、每场测试和每份家庭作业在提交的瞬间即可获得批改。每天在直播课中练习口语，剩下的交给 AI 处理——即时反馈，无需等待答疑时间。",
    "services_btn_explore": "探索工具箱",
