    "cookie_desc": "نحن نستخدم ملفات تعريف الارتباط لتحسين تجربة تعلمك وتحليل حركة المرور على موقعنا. بالنقر فوق 'قبول الكل'، فإنك توافق على استخدامنا لملفات تعريف الارتباط. اقرأ <a href=\"cookies.html\">سياسة ملفات تعريف الارتباط</a> لمزيد من التفاصيل.",
