    "corporate_why_title": "طلاقة الموظفين",
    "corporate_why_1_title": "معلمون متخصصون في التوطين والترحال",
    "corporate_why_1_desc": "خبراء لغة محليون متخصصون في دمج المغتربين، وثقافة الأعمال المحلية، والحديث المهني.",
    "corporate_why_2_title": "مجموعات مخصصة للأدوار الوظيفية",
    "corporate_why_2_desc": "يتعلم الموظفون معًا في مجموعات صغيرة مقسمة حسب تخصص العمل، مما يتيح ممارسة سيناريوهات حقيقية للعمل.",
    "corporate_why_3_title": "تقدم يعتمد على الذكاء الاصطناعي",
    "corporate_why_3_desc": "يقوم محرك الذكاء الاصطناعي بتصحيح الواجبات وتدريبات المفردات تلقائياً، لزيادة ساعات التحدث المباشر مع المعلمين.",
    "corporate_why_4_title": "لوحة تحكم مسؤولي الموارد البشرية",
    "corporate_why_4_desc": "تابع الحضور وساعات التحدث الفعلية ومستويات الإطار الأوروبي (CEFR) بتحليلات دقيقة في الوقت الفعلي.",
    "corporate_process_title": "كيف نعمل؟",
    "corporate_step_1_title": "1. تقييم المهارات",
    "corporate_step_1_desc": "نقيّم مستويات الحديث لموظفيك ونربطها مع بلدان جهة العمل ووجهة السفر الجديدة.",
    "corporate_step_2_title": "2. مجموعات خاصة مخصصة",
    "corporate_step_2_desc": "ينضم الموظفون إلى صفوف محادثة مهنية خاصة تتناسب مع تخصصاتهم وأهدافهم اللغوية.",
    "corporate_step_3_title": "3. الانطلاق والمتابعة",
    "corporate_step_3_desc": "تبدأ الفصول حسب جدولك، ويتلقى مسؤولو الموارد البشرية تقارير حضور وتقارير تقدم شهرية.",
