    "corporate_t1_desc": "مع 18 عاماً من الخبرة، تتخصص Sarah في التأهيل المكثف لنقل التنفيذيين والمدراء إلى إسبانيا وأمريكا اللاتينية.",
    "corporate_t2_desc": "تتمتع Jessica بخبرة 22 عاماً في التدريب اللغوي للشركات، حيث تقوم بإنشاء مصطلحات مخصصة لفرق الدعم الفني، المالية والهندسة.",
    "corporate_t3_desc": "خبير لغوي ثنائي اللغة وخبرة 15 عاماً في تدريب المغتربين. تقود مارتينا صفوف الاندماج والاتيكيت المهني المحلي.",
    "corporate_t4_desc": "مع 20 عاماً من تدريب التنفيذيين في الشركات متعددة الجنسيات، يقدم Kevin وحدات مكثفة للكتابة المهنية، العروض، والمفاوضات.",
