    "corp_huge_slide_2": "94% من المهام الدولية تفشل عندما <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">يتم تجاهل الاستعداد اللغوي</span>.",
    "corp_huge_slide_3": "فشل النقل مكلف للغاية. الاستعداد اللغوي هو <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">درع الحماية الأقوى لك</span>.",
    "corp_huge_slide_4": "الفرق ثنائية اللغة تبني <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">ثقة فورية ومصداقية محلية</span>.",
    "corp_huge_slide_5": "الطلاقة تطلق العنان للعمليات المحلية، <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">وتقلل من فترات التوقف والاختناقات</span>.",
    "corp_huge_slide_6": "نمّ مهارات موظفيك المغتربين من خلال <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">صفوف مهنية مخصصة للشركات</span>.",
