    "careers_process_title": "Processo di Selezione",
    "careers_process_desc": "Accettiamo meno del 5% dei candidati per mantenere un livello di insegnamento premium.",
    "careers_step_1_title": "Candidatura Online",
    "careers_step_1_desc": "Invia il tuo CV, credenziali di insegnamento e un breve video di presentazione di 2 minuti.",
