    "tiers_pc_line_3": "Trois cours en groupe et une séance individuelle par semaine, environ 17 par mois, pour {price} par mois.",
    "tiers_pc_line_4": "Trois cours particuliers par semaine, environ 13 par mois, pour {price} par mois.",
    "tiers_pc_year": "Avec la formule annuelle : environ {price} par cours.",
    "tiers_faq_title": "Questions sur les formules et les prix",
    "tiers_faq_q1": "Puis-je résilier à tout moment ?",
    "tiers_faq_a1": "Oui. Vous pouvez résilier à tout moment dans les paramètres de paiement de votre compte, et vous gardez l’accès jusqu’à la fin de la période payée, comme le prévoient les Conditions générales.",
    "tiers_faq_q2": "Comment fonctionne la formule annuelle ?",
    "tiers_faq_a2": "Vous payez une fois par an et vous avez douze mois pour le prix de dix. Community, par exemple, coûte 240 € par an au lieu de 24 € chaque mois.",
    "tiers_faq_q3": "Puis-je changer de formule plus tard ?",
    "tiers_faq_a3": "Oui. Vous pouvez passer à une autre formule quand vos objectifs évoluent. Si vous avez besoin d’aide pour choisir, écrivez-nous depuis la page de contact.",
    "tiers_faq_q4": "Dans quelle devise vais-je payer ?",
    "tiers_faq_a4": "Les prix s’affichent dans votre devise quand c’est possible, en euros, dollars américains, canadiens ou australiens ou dirhams marocains, et vous payez dans la devise affichée sur la page.",
    "tiers_faq_q5": "Et si ma langue n’est pas encore ouverte ?",
    "tiers_faq_a5": "Vous pouvez rejoindre gratuitement sa liste d’attente sans rien payer aujourd’hui. Nous vous écrivons dès l’ouverture des cours dans votre langue, et les cours d’anglais et d’allemand sont déjà ouverts.",
    "services_hero_title_v2": "Cours de langues en ligne",
    "services_hero_desc_v2": "Des cours en direct par vidéo avec votre professeur et toujours le même groupe, à jours fixes chaque semaine. Entre les cours, les exercices et les tests sont corrigés dès que vous répondez, et votre professeur corrige vos devoirs.",
