    "corp_features_title": "Pourquoi Alimun fonctionne pour les entreprises",
    "corp_feature_1_title": "Programmes par poste",
    "corp_feature_1_desc": "Vocabulaire et scénarios sur mesure conçus pour vos équipes commerciales, service client ou techniques.",
    "corp_feature_2_title": "Groupes actifs",
